/**
 * Strings a regular expression matches, generated by walking its pattern: literals, escapes, classes, groups,
 * alternatives and quantifiers. Lookarounds and anchors generate nothing; `example()` retries until the whole regex,
 * lookarounds included, matches what was generated. For tests, which need a token of every format without storing
 * secret-shaped strings.
 */

type Node =
	| { kind: "chars"; set: string }
	| { kind: "seq"; items: Node[] }
	| { kind: "alt"; options: Node[] }
	| { kind: "repeat"; node: Node; min: number; max: number }
	/** A positive lookbehind: text that comes before the match, generated in front of it. */
	| { kind: "before"; node: Node }
	| { kind: "empty" };

const PRINTABLE = Array.from({ length: 95 }, (_, i) => String.fromCharCode(32 + i)).join("");
const DIGITS = "0123456789";
const WORD = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_";
const SPACE = " \t";
/** How far an open-ended quantifier (`*`, `+`, `{n,}`) goes past its minimum. */
const OPEN_EXTRA = 24;

class Parser {
	private i = 0;
	private readonly src: string;
	constructor(src: string) {
		this.src = src;
	}

	parse(): Node {
		const node = this.alternatives();
		if (this.i < this.src.length) throw new Error(`unparsed at ${this.i}: ${this.src.slice(this.i, this.i + 20)}`);
		return node;
	}

	private alternatives(): Node {
		const options = [this.sequence()];
		while (this.src[this.i] === "|") {
			this.i++;
			options.push(this.sequence());
		}
		return options.length === 1 ? options[0] : { kind: "alt", options };
	}

	private sequence(): Node {
		const items: Node[] = [];
		while (this.i < this.src.length && this.src[this.i] !== "|" && this.src[this.i] !== ")")
			items.push(this.quantified(this.atom()));
		return { kind: "seq", items };
	}

	private quantified(node: Node): Node {
		const c = this.src[this.i];
		let min = 1;
		let max = 1;
		if (c === "*" || c === "+" || c === "?") {
			this.i++;
			[min, max] = c === "*" ? [0, OPEN_EXTRA] : c === "+" ? [1, 1 + OPEN_EXTRA] : [0, 1];
		} else if (c === "{" && /^\{\d+(?:,\d*)?\}/.test(this.src.slice(this.i))) {
			const m = /^\{(\d+)(?:(,)(\d*))?\}/.exec(this.src.slice(this.i))!;
			this.i += m[0].length;
			min = Number(m[1]);
			max = m[2] ? (m[3] ? Number(m[3]) : min + OPEN_EXTRA) : min;
		} else return node;
		if (this.src[this.i] === "?") this.i++; // lazy: the same strings
		return this.quantified({ kind: "repeat", node, min, max });
	}

	private atom(): Node {
		const c = this.src[this.i++];
		if (c === "(") {
			let group = "";
			if (this.src[this.i] === "?") {
				group = /^\?(?::|=|!|<=|<!|<[A-Za-z_]\w*>)/.exec(this.src.slice(this.i))![0];
				this.i += group.length;
			}
			const inner = this.alternatives();
			this.i++; // `)`
			if (group === "?<=") return { kind: "before", node: inner };
			return /^\?(?:=|!|<!)$/.test(group) ? { kind: "empty" } : inner;
		}
		if (c === "[") return this.charClass();
		if (c === "\\") return this.escape(false) as Node;
		if (c === "^" || c === "$") return { kind: "empty" };
		if (c === ".") return { kind: "chars", set: PRINTABLE };
		return { kind: "chars", set: c };
	}

	/** An escape after its backslash: a class (`\d`), an anchor (`\b`), a back reference, or a character. */
	private escape(inClass: boolean): Node | string {
		const c = this.src[this.i++];
		if (c === "d") return inClass ? DIGITS : { kind: "chars", set: DIGITS };
		if (c === "w") return inClass ? WORD : { kind: "chars", set: WORD };
		if (c === "s") return inClass ? SPACE : { kind: "chars", set: SPACE };
		if (!inClass && (c === "b" || c === "B")) return { kind: "empty" };
		if (c === "D" || c === "W" || c === "S") {
			const not = c === "D" ? DIGITS : c === "W" ? WORD : SPACE;
			const set = [...PRINTABLE].filter((x) => !not.includes(x)).join("");
			return inClass ? set : { kind: "chars", set };
		}
		if (/\d/.test(c) && !inClass) throw new Error("back reference");
		const ch =
			c === "n"
				? "\n"
				: c === "r"
					? "\r"
					: c === "t"
						? "\t"
						: c === "x"
							? String.fromCharCode(parseInt(this.take(2), 16))
							: c === "u"
								? String.fromCharCode(parseInt(this.take(4), 16))
								: c;
		return inClass ? ch : { kind: "chars", set: ch };
	}

	private take(n: number): string {
		const s = this.src.slice(this.i, this.i + n);
		this.i += n;
		return s;
	}

	private charClass(): Node {
		const negate = this.src[this.i] === "^";
		if (negate) this.i++;
		let set = "";
		let first = true;
		while (this.src[this.i] !== "]" || first) {
			first = false;
			let from = this.src[this.i++];
			if (from === "\\") {
				const e = this.escape(true) as string;
				if (e.length > 1) {
					set += e;
					continue;
				}
				from = e;
			}
			if (this.src[this.i] === "-" && this.src[this.i + 1] !== "]") {
				this.i++;
				let to = this.src[this.i++];
				if (to === "\\") to = this.escape(true) as string;
				for (let x = from.charCodeAt(0); x <= to.charCodeAt(0); x++) set += String.fromCharCode(x);
			} else set += from;
		}
		this.i++; // `]`
		return { kind: "chars", set: negate ? [...PRINTABLE].filter((x) => !set.includes(x)).join("") : set };
	}
}

function generate(node: Node, random: () => number): string {
	switch (node.kind) {
		case "chars":
			return node.set[Math.floor(random() * node.set.length)] ?? "";
		case "seq":
			return node.items.map((n) => generate(n, random)).join("");
		case "alt":
			// (The first option half the time: an option guarded by a lookahead, `\.(?=\w)`, is usually a rare one.)
			return generate(node.options[random() < 0.5 ? 0 : Math.floor(random() * node.options.length)], random);
		case "repeat": {
			const n = node.min + Math.floor(random() * (node.max - node.min + 1));
			return Array.from({ length: n }, () => generate(node.node, random)).join("");
		}
		case "before":
			return generate(node.node, random);
		case "empty":
			return "";
	}
}

/**
 * A text `re` matches from its start to its end, its lookarounds included (a positive lookbehind's text comes first),
 * or undefined after `tries` attempts.
 */
export function example(re: RegExp, random: () => number, tries = 200): string | undefined {
	const tree = new Parser(re.source).parse();
	const once = new RegExp(re.source, re.flags.replace(/[gy]/g, ""));
	for (let n = 0; n < tries; n++) {
		const s = generate(tree, random);
		const m = once.exec(s);
		if (m && m.index + m[0].length === s.length) return s;
	}
	return undefined;
}
